using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed record CierreEvaluado(
    string Texto,
    IReadOnlyList<Cita> Citas,
    ResultadoAuditoria Resultado,
    bool? UsoDatos,
    bool Bloqueado,
    string? MotivoDeReintento)
{
    public static CierreEvaluado Entregable(string texto, IReadOnlyList<Cita> citas, ResultadoAuditoria resultado, bool? usoDatos = null) =>
        new(texto, citas, resultado, usoDatos, false, null);
}

internal sealed class CierreDeRespuesta
{
    private readonly IBaseConocimiento _baseConocimiento;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly VerificadorSalida _verificadorSalida;
    private readonly ConfiguracionAsistente _configuracion;
    private readonly CitasDeRespuesta _citasDeRespuesta;
    private readonly CitasDeReglasAplicadas _citasDeReglas;
    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;
    private readonly DefinitivaPorAsignatura _definitivaPorAsignatura;

    public CierreDeRespuesta(
        IBaseConocimiento baseConocimiento,
        PoliticaAcceso politicaAcceso,
        VerificadorSalida verificadorSalida,
        ConfiguracionAsistente configuracion)
    {
        _baseConocimiento = baseConocimiento;
        _politicaAcceso = politicaAcceso;
        _verificadorSalida = verificadorSalida;
        _configuracion = configuracion;
        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
        _definitivaPorAsignatura = new DefinitivaPorAsignatura(configuracion.Catalogo);
        _citasDeReglas = new CitasDeReglasAplicadas(baseConocimiento, _definitivaPorAsignatura);
        _afirmacionesDePerdida = new AfirmacionesDePerdida(configuracion.Catalogo);
    }

    public CierreEvaluado Evaluar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
    {
        if (texto.Trim() == Textos.SinInformacion)
        {
            return CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion);
        }

        var escritas = EscritasValidas(sesion, texto, entrada);
        var limpio = Textos.CitasDeTextoFijo(texto) is null ? ReferenciasEscritas.Limpiar(texto, escritas) : texto;
        return ReferenciasEscritas.TieneContenido(limpio)
            ? Verificar(sesion, limpio, escritas, entrada)
            : CierreEvaluado.Entregable(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion);
    }

    private IReadOnlyList<Cita> EscritasValidas(SesionPregunta sesion, string texto, EntradaConversacion entrada) =>
        _verificadorSalida.DescartarCitasInexistentes(
            _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, sesion.Registro.Reglas),
            _baseConocimiento);

    private CierreEvaluado Verificar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, sesion.Directorio);
        var verificada = _verificadorSalida.Verificar(
            sesion.Entrada.Usuario,
            limpio,
            escritas,
            autorizados,
            sesion.Registro.Fuentes,
            _baseConocimiento,
            sesion.Directorio,
            Confidencial(sesion, entrada));
        if (verificada.Resultado != ResultadoAuditoria.Respondida)
        {
            return new CierreEvaluado(verificada.Respuesta, verificada.Citas, verificada.Resultado, null, true, verificada.MotivoDeReintento);
        }

        var motivo = MotivoDeAfirmacionNoVerificable(sesion, limpio, autorizados);
        return motivo is null
            ? Completar(sesion, limpio, escritas, entrada)
            : new CierreEvaluado(Textos.NoVerificable, [], ResultadoAuditoria.EstadoNoVerificado, null, true, motivo);
    }

    private string? MotivoDeAfirmacionNoVerificable(SesionPregunta sesion, string respuesta, IReadOnlyCollection<string> autorizados)
    {
        var usuario = sesion.Entrada.Usuario;
        var bloques = BloquesDeRespuesta.De(respuesta);
        var resumenes = sesion.Registro.Resumenes;
        return _afirmacionesDePerdida.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes)
            ?? _definitivaPorAsignatura.Motivo(bloques, usuario, autorizados, sesion.Directorio, resumenes);
    }

    private CierreEvaluado Completar(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var citasDeTextoFijo = Textos.CitasDeTextoFijo(limpio);
        if (citasDeTextoFijo is not null)
        {
            return CierreEvaluado.Entregable(limpio, citasDeTextoFijo, ResultadoAuditoria.Respondida);
        }

        var documentos = CitasDeDocumento(sesion, limpio, escritas, entrada);
        if (documentos.Count == 0 && !sesion.Registro.UsoDatos)
        {
            return new CierreEvaluado(Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, false, true, null);
        }

        IReadOnlyList<Cita> citas = [.. documentos.Concat(sesion.Registro.Citas).Distinct()];
        return CierreEvaluado.Entregable(limpio, citas, ResultadoAuditoria.Respondida);
    }

    private IReadOnlyList<Cita> CitasDeDocumento(SesionPregunta sesion, string limpio, IReadOnlyList<Cita> escritas, EntradaConversacion entrada)
    {
        var reglas = _citasDeReglas.De(sesion.Registro, sesion.Entrada.Pregunta, limpio, escritas, sesion.Directorio);
        IReadOnlyList<Cita> sinRespaldo = [.. escritas.Concat(reglas).Concat(_citasDeRespuesta.PorTema(limpio, entrada.Secciones)).Distinct()];
        return sinRespaldo.Count > 0 ? sinRespaldo : _citasDeRespuesta.Respaldo(limpio, entrada.Secciones);
    }

    private MaterialConfidencial Confidencial(SesionPregunta sesion, EntradaConversacion entrada) =>
        new(
            _configuracion.MarcadorCanario,
            [ConstructorPrompts.Instrucciones(entrada.PromptSistema), .. DescripcionesDeHerramientas(sesion.Entrada.Usuario.Rol)],
            HerramientasAsistente.NombresInternos);

    private static IEnumerable<string> DescripcionesDeHerramientas(Rol rol) =>
        HerramientasAsistente.Definir(rol)
            .SelectMany(herramienta => herramienta.Parametros.Select(parametro => parametro.Descripcion).Prepend(herramienta.Descripcion));
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal static partial class ReferenciasEscritas
{
    internal const char Marca = '';
    private const string DocumentoDerogado = "reglamento_academico_2023.md";
    private const string LetrasDeNombre = @"[\p{L}\p{N}_-]";
    private const string Numero = @"\d+(?:\.\d+)*";
    private const string ReferenciaASeccion =
        @"(?<![\p{L}\p{N}])(?:secci[oó]n(?:es)?|art[ií]culos?|art\.?|§)\s*" + Numero + @"(?:\s*(?:,|y|e)\s*" + Numero + ")*";
    private const string ConectorDeReferencia =
        @"(?:(?<!" + LetrasDeNombre + @")(?:seg[uú]n|de\s+acuerdo\s+con|conforme\s+al?|ver|consulta|se\s+respaldan?\s+en|en|del?)(?:\s+(?:el|la|los|las))?"
        + @"|(?<!" + LetrasDeNombre + @")(?:el|la|los|las))\s+$";

    public static string Limpiar(string respuesta, IReadOnlyList<Cita> citas)
    {
        var marcada = AtribucionGenerica.Marcar(MarcarReferenciasInvalidas(respuesta, citas), citas);
        marcada = FraseFijaAnexada(marcada);
        return marcada.Contains(Marca, StringComparison.Ordinal) ? LimpiezaDeOraciones.Depurar(marcada) : respuesta;
    }

    public static bool TieneContenido(string texto) => PalabraDeLetras().IsMatch(texto) || CifraDeContenido().IsMatch(texto);

    private static string MarcarReferenciasInvalidas(string respuesta, IReadOnlyList<Cita> citas)
    {
        var invalidas = Unir(DocumentosEscritos.En(respuesta).Select(documento => Ampliar(respuesta, documento, citas)))
            .Where(rango => !rango.Valida)
            .Select(rango => rango with { Inicio = ConConector(respuesta, rango.Inicio) })
            .OrderByDescending(rango => rango.Inicio);
        var texto = respuesta;
        foreach (var rango in invalidas)
        {
            texto = string.Concat(texto.AsSpan(0, rango.Inicio), Marca.ToString(), texto.AsSpan(rango.Fin));
        }

        return texto;
    }

    private static RangoDeReferencia Ampliar(string texto, DocumentoEscrito documento, IReadOnlyList<Cita> citas)
    {
        var derecha = SeccionesALaDerecha().Match(texto, documento.Fin);
        var izquierda = SeccionALaIzquierda().Match(texto[..documento.Inicio]);
        var numeros = (izquierda.Success ? NumerosDe(izquierda.Groups["sec"].Value) : [])
            .Concat(derecha.Groups["sec"].Captures.SelectMany(captura => NumerosDe(captura.Value)))
            .ToList();
        var inicio = izquierda.Success ? izquierda.Index : documento.Inicio;
        return new RangoDeReferencia(inicio, derecha.Index + derecha.Length, EsValida(documento.Nombre, numeros, citas));
    }

    private static List<RangoDeReferencia> Unir(IEnumerable<RangoDeReferencia> rangos)
    {
        var unidos = new List<RangoDeReferencia>();
        foreach (var rango in rangos.OrderBy(rango => rango.Inicio))
        {
            unidos.AddRange(unidos.Count > 0 && rango.Inicio <= unidos[^1].Fin ? Fusionar(unidos, rango) : [rango]);
        }

        return unidos;
    }

    private static List<RangoDeReferencia> Fusionar(List<RangoDeReferencia> unidos, RangoDeReferencia rango)
    {
        var ultimo = unidos[^1];
        unidos.RemoveAt(unidos.Count - 1);
        return [new RangoDeReferencia(ultimo.Inicio, Math.Max(ultimo.Fin, rango.Fin), ultimo.Valida && rango.Valida)];
    }

    private static int ConConector(string texto, int inicio)
    {
        var conector = Conector().Match(texto[..inicio]);
        return conector.Success ? conector.Index : inicio;
    }

    private static bool EsValida(string documento, List<string> numeros, IReadOnlyList<Cita> citas) =>
        numeros.Count == 0
            ? string.Equals(documento, DocumentoDerogado, StringComparison.OrdinalIgnoreCase) || citas.Any(cita => MismoDocumento(cita, documento))
            : numeros.All(numero => citas.Any(cita => MismoDocumento(cita, documento) && NumeroDeCita(cita) == numero));

    private static bool MismoDocumento(Cita cita, string documento) =>
        documento.All(char.IsAscii) && string.Equals(cita.Documento, documento, StringComparison.OrdinalIgnoreCase);

    private static string? NumeroDeCita(Cita cita) => NumeroDeSeccion().Matches(cita.Seccion).LastOrDefault()?.Value;

    private static IEnumerable<string> NumerosDe(string seccion) => NumeroDeSeccion().Matches(seccion).Select(numero => numero.Value);

    private static string FraseFijaAnexada(string texto)
    {
        var sinFrase = Regex.Replace(texto, Regex.Escape(Textos.SinInformacion), Marca.ToString(), RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos));
        return TieneContenido(sinFrase.Replace(Marca, ' ')) ? sinFrase : texto;
    }

    private sealed record RangoDeReferencia(int Inicio, int Fin, bool Valida);

    [GeneratedRegex(@"\G(?:\s*[·,:-]\s*(?<sec>" + ReferenciaASeccion + "))*", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SeccionesALaDerecha();

    [GeneratedRegex(@"(?<sec>" + ReferenciaASeccion + @")\s+(?:de\s+la|del|de|en\s+el|en)\s+$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SeccionALaIzquierda();

    [GeneratedRegex(ConectorDeReferencia, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex Conector();

    [GeneratedRegex(@"\d+(?:\.\d+)*", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex NumeroDeSeccion();

    [GeneratedRegex(@"\p{L}{2,}", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraDeLetras();

    [GeneratedRegex(@"(?<![\d.])\d\.\d{1,2}(?!\d)|(?<![\d.])\d+(?:\.\d{1,2})?\s*%", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CifraDeContenido();
}
using System.Text.RegularExpressions;

namespace TutorFlow.Core.Asistente;

internal static partial class LimpiezaDeOraciones
{
    private const int PalabrasMinimasPorOracion = 3;
    private const string EspacioEnBlanco = " ";

    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos);

    private static readonly (Regex Patron, string Reemplazo)[] ReglasDeSignos =
    [
        (new Regex(@"[\(\[][\s·,;:]*[\)\]]", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
        (new Regex(@" {2,}", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
